 private UsernamePasswordAuthenticationToken auth(boolean escribir,boolean fin){var a=new ArrayList<SimpleGrantedAuthority>();for(String p:List.of("EMPLEADO_LEER","EMPLEADO_LABORAL_LEER",escribir?"CONDICION_SALARIAL_ADMINISTRAR":"CONDICION_SALARIAL_LEER"))a.add(new SimpleGrantedAuthority(p));if(fin)a.add(new SimpleGrantedAuthority("MOVIMIENTO_FINANCIERO_REGISTRAR"));return new UsernamePasswordAuthenticationToken(new UsuarioPrincipal(430000L,430000L,Set.of(),true,false,"qa.prestamos","",a),"",a);}
 private void sesion(){SecurityContextHolder.getContext().setAuthentication(auth(true,true));}
 private MockHttpSession web(boolean escribir,boolean fin){var s=new MockHttpSession();s.setAttribute("SPRING_SECURITY_CONTEXT",new SecurityContextImpl(auth(escribir,fin)));return s;}
 private PrestamoEmpleadoForm form(PrestamoEmpleadoService s){var c=s.concepto(430010L,430000L);var f=new PrestamoEmpleadoForm();f.setConceptoId(c.id());f.setConceptoTexto(c.texto());f.setConceptoVersion(c.version());f.setImporte(new BigDecimal("3000"));f.setParcialidad(new BigDecimal("500"));f.setPrimerDescuento(LocalDate.of(2030,6,1));f.setMotivo("Préstamo de capacitación sin dinero real");return f;}
 private EntregarPrestamoForm entrega(Long version){var f=new EntregarPrestamoForm();f.setVersion(version);f.setCuentaId(430000L);f.setCuentaTexto("CAJA-QA · Cuenta ficticia");f.setMotivoPagoId(430000L);f.setReferencia("EVIDENCIA-QA-01");f.setMotivo("Entrega completamente ficticia en base aislada");f.setEntregaConfirmada(true);return f;}
 private Long periodo(ProgramacionNominaService p,Long cal,int mes){var c=p.contexto(cal);var f=new PeriodoNominaForm();f.setCalendarioId(cal);f.setCalendarioTexto(c.calendario());f.setCalendarioVersion(c.version());f.setCodigo("PRE-2030-"+mes);f.setNombre("Periodo ficticio préstamo");f.setInicio(LocalDate.of(2030,mes,1));f.setFin(f.getInicio().withDayOfMonth(f.getInicio().lengthOfMonth()));f.setPago(f.getFin());f.setMotivo("Prueba aislada");return p.guardarPeriodo(null,f);}
